assistant/bridge.py:
"""In-browser bridge: the REST API's routes as a plain function call.

The GitHub Pages demo runs this assistant inside the visitor's browser with Pyodide
(Python compiled to WebAssembly). There is no server there, so the web console sends its
requests to `dispatch()` instead of over HTTP. Same assistant code, same JSON.
"""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any
from urllib.parse import parse_qs, unquote, urlsplit

from .config import Settings
from .core import Assistant, Forbidden, NotFound
from .evaluation import load_cases, run_eval
from .gateway import ProviderError, list_providers

_assistant: Assistant | None = None


def assistant() -> Assistant:
    global _assistant
    if _assistant is None:
        _assistant = Assistant(Settings())
    return _assistant


def reset() -> None:
    global _assistant
    _assistant = None


def _need(body: dict[str, Any], *keys: str) -> list[Any]:
    missing = [k for k in keys if not body.get(k)]
    if missing:
        raise ValueError(f"Missing field(s): {', '.join(missing)}")
    return [body[k] for k in keys]


def _route(method: str, path: str, query: dict[str, str], body: dict[str, Any]) -> Any:
    a = assistant()
    m = re.fullmatch
    if method == "GET" and path == "/api/health":
        return {"status": "ok", "provider": "offline", "runtime": "browser", "auth": False}
    if method == "GET" and path == "/api/providers":
        return [p for p in list_providers(a.settings) if p["name"] == "offline"]
    if method == "GET" and path == "/api/users":
        return a.users()
    if method == "POST" and path == "/api/ask":
        user, question = _need(body, "user", "question")
        return a.ask(user, question, body.get("mode", "grounded"))
    if path == "/api/documents":
        if method == "GET":
            return a.documents(query.get("user", ""))
        user, title, text = _need(body, "user", "title", "text")
        return a.add_document(user, title, text, body.get("audience") or [], body.get("supersedes") or None)
    if (g := m(r"/api/documents/([\w-]+)/approve", path)) and method == "POST":
        return a.approve(_need(body, "user")[0], g.group(1))
    if (g := m(r"/api/documents/([\w-]+)", path)) and method == "GET":
        return a.document(query.get("user", ""), g.group(1))
    if method == "GET" and path == "/api/graph":
        return a.graph_snapshot(query.get("user", ""))
    if method == "POST" and path == "/api/eval":
        name = "eval_holdout.json" if body.get("holdout") else "eval.json"
        # A fresh assistant, so documents added or approved in the demo don't change the score.
        return run_eval(Assistant(a.settings), cases=load_cases(Path(a.settings.knowledge_path) / name))
    if method == "GET" and path == "/api/audit":
        return a.audit[-200:]
    raise NotFound(f"No route for {method} {path}")


def dispatch(method: str, url: str, body_json: str = "null") -> str:
    """Handle one request. Returns JSON: {"status": int, "data": ...}."""
    parts = urlsplit(url)
    query = {k: v[-1] for k, v in parse_qs(parts.query).items()}
    try:
        body = json.loads(body_json) or {}
        data = _route(method.upper(), unquote(parts.path), query, body)
        status = 200
    except NotFound as exc:
        status, data = 404, {"detail": str(exc)}
    except Forbidden as exc:
        status, data = 403, {"detail": str(exc)}
    except ProviderError as exc:
        status, data = 400, {"detail": str(exc)}
    except ValueError as exc:
        status, data = 422, {"detail": str(exc)}
    return json.dumps({"status": status, "data": data})

assistant/gateway.py:
"""Model gateway: one interface for every model, cloud or local.

Engine code calls `provider.complete(system, user)` and never imports a vendor SDK, so
switching Bedrock -> Anthropic -> OpenAI -> a local model on Ollama is a config change.
`offline` uses no model: answers are quoted sentences, which keeps the public demo free
and lets the assistant run fully air-gapped.
"""

from __future__ import annotations

import json
import os
from collections.abc import Callable, Sequence
from typing import Any, Protocol

from .config import Settings


class ProviderError(RuntimeError):
    pass


class LLMProvider(Protocol):
    name: str
    model: str

    def complete(self, system: str, user: str, json_mode: bool = False) -> str: ...


def _post(url: str, headers: dict[str, str], payload: dict[str, Any]) -> dict[str, Any]:
    import httpx  # imported lazily so the browser demo doesn't need it

    try:
        resp = httpx.post(url, headers=headers, json=payload, timeout=httpx.Timeout(90.0, connect=10.0))
    except httpx.HTTPError as exc:
        raise ProviderError(f"Could not reach {url}: {exc}") from exc
    if resp.status_code >= 400:
        raise ProviderError(f"{url} returned {resp.status_code}: {resp.text[:300]}")
    return resp.json()


class OpenAIProvider:
    name = "openai"

    def __init__(self, settings: Settings) -> None:
        self.model = settings.openai_model
        self.key = os.environ.get("OPENAI_API_KEY", "")
        self.base = os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")

    def complete(self, system: str, user: str, json_mode: bool = False) -> str:
        payload: dict[str, Any] = {
            "model": self.model,
            "temperature": 0,
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
        }
        if json_mode:
            payload["response_format"] = {"type": "json_object"}
        data = _post(f"{self.base}/chat/completions", {"Authorization": f"Bearer {self.key}"}, payload)
        return data["choices"][0]["message"]["content"]


class AnthropicProvider:
    name = "anthropic"

    def __init__(self, settings: Settings) -> None:
        self.model = settings.anthropic_model
        self.key = os.environ.get("ANTHROPIC_API_KEY", "")

    def complete(self, system: str, user: str, json_mode: bool = False) -> str:
        if not self.model:
            raise ProviderError("Set ANTHROPIC_MODEL to the Anthropic model id you want to use")
        data = _post(
            "https://api.anthropic.com/v1/messages",
            {"x-api-key": self.key, "anthropic-version": "2023-06-01"},
            {
                "model": self.model,
                "max_tokens": 1024,
                "temperature": 0,
                "system": system + ("\nRespond with a single JSON object and nothing else." if json_mode else ""),
                "messages": [{"role": "user", "content": user}],
            },
        )
        return "".join(block.get("text", "") for block in data.get("content", []))


class BedrockProvider:
    """Amazon Bedrock via the Converse API (works with Amazon Nova, Llama, Mistral and other Bedrock models)."""

    name = "bedrock"

    def __init__(self, settings: Settings) -> None:
        self.model = settings.bedrock_model
        self.region = settings.aws_region
        self._client: Any = None

    def complete(self, system: str, user: str, json_mode: bool = False) -> str:
        if self._client is None:
            try:
                import boto3
            except ImportError as exc:
                raise ProviderError("Bedrock needs boto3: pip install boto3") from exc
            self._client = boto3.client("bedrock-runtime", region_name=self.region)
        try:
            resp = self._client.converse(
                modelId=self.model,
                system=[{"text": system + ("\nRespond with JSON only." if json_mode else "")}],
                messages=[{"role": "user", "content": [{"text": user}]}],
                inferenceConfig={"temperature": 0, "maxTokens": 1024},
            )
        except Exception as exc:  # botocore raises many types
            raise ProviderError(f"Bedrock call failed: {exc}") from exc
        return "".join(part.get("text", "") for part in resp["output"]["message"]["content"])


class OllamaProvider:
    """Local models (Llama, Gemma, Mistral) for offline or air-gapped deployments."""

    name = "ollama"

    def __init__(self, settings: Settings) -> None:
        self.model = settings.ollama_model
        self.url = settings.ollama_url

    def complete(self, system: str, user: str, json_mode: bool = False) -> str:
        payload: dict[str, Any] = {
            "model": self.model,
            "stream": False,
            "options": {"temperature": 0},
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
        }
        if json_mode:
            payload["format"] = "json"
        return _post(f"{self.url}/api/chat", {}, payload)["message"]["content"]


PROVIDERS: dict[str, Callable[[Settings], LLMProvider]] = {
    "openai": OpenAIProvider,
    "anthropic": AnthropicProvider,
    "bedrock": BedrockProvider,
    "ollama": OllamaProvider,
}


def is_configured(name: str) -> bool:
    env = os.environ.get
    return {
        "offline": True,
        "openai": bool(env("OPENAI_API_KEY")),
        "anthropic": bool(env("ANTHROPIC_API_KEY") and env("ANTHROPIC_MODEL")),
        "bedrock": bool(env("AWS_ACCESS_KEY_ID") or env("AWS_PROFILE") or env("AWS_ROLE_ARN")),
        "ollama": bool(env("OLLAMA_URL")),
    }.get(name, name in PROVIDERS)


def get_provider(name: str, settings: Settings) -> LLMProvider | None:
    """The LLM provider, or None for the offline (extractive) answerer."""
    name = name.lower()
    if name == "offline":
        return None
    if name not in PROVIDERS:
        raise ProviderError(f"Unknown provider {name!r}. Choose from: offline, {', '.join(PROVIDERS)}")
    return PROVIDERS[name](settings)


def list_providers(settings: Settings) -> list[dict[str, Any]]:
    models = {
        "offline": "extractive (no model)",
        "openai": settings.openai_model,
        "anthropic": settings.anthropic_model or "set ANTHROPIC_MODEL",
        "bedrock": settings.bedrock_model,
        "ollama": settings.ollama_model,
    }
    return [
        {"name": n, "model": models.get(n, "custom"), "configured": is_configured(n), "default": n == settings.provider}
        for n in ["offline", *PROVIDERS]
    ]


# ---------- embedders ----------


class OpenAIEmbedder:
    def __init__(self, settings: Settings) -> None:
        self.model = settings.openai_embed_model
        self.name = f"openai:{self.model}"
        self.key = os.environ.get("OPENAI_API_KEY", "")
        self.base = os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")

    def embed(self, texts: Sequence[str]) -> list[list[float]]:
        out: list[list[float]] = []
        for i in range(0, len(texts), 96):
            data = _post(
                f"{self.base}/embeddings",
                {"Authorization": f"Bearer {self.key}"},
                {"model": self.model, "input": list(texts[i : i + 96])},
            )
            out.extend(item["embedding"] for item in sorted(data["data"], key=lambda d: d["index"]))
        return [_unit(v) for v in out]


class OllamaEmbedder:
    def __init__(self, settings: Settings) -> None:
        self.model = settings.ollama_embed_model
        self.name = f"ollama:{self.model}"
        self.url = settings.ollama_url

    def embed(self, texts: Sequence[str]) -> list[list[float]]:
        return [
            _unit(v)
            for v in _post(f"{self.url}/api/embed", {}, {"model": self.model, "input": list(texts)})["embeddings"]
        ]


class BedrockEmbedder:
    """Amazon Titan text embeddings on Bedrock."""

    def __init__(self, settings: Settings) -> None:
        self.model = settings.bedrock_embed_model
        self.name = f"bedrock:{self.model}"
        self.region = settings.aws_region
        self._client: Any = None

    def embed(self, texts: Sequence[str]) -> list[list[float]]:
        if self._client is None:
            import boto3

            self._client = boto3.client("bedrock-runtime", region_name=self.region)
        out = []
        for text in texts:
            resp = self._client.invoke_model(modelId=self.model, body=json.dumps({"inputText": text}))
            out.append(_unit(json.loads(resp["body"].read())["embedding"]))
        return out


def _unit(v: Sequence[float]) -> list[float]:
    norm = sum(x * x for x in v) ** 0.5 or 1.0
    return [x / norm for x in v]


def get_embedder(settings: Settings) -> Any:
    from .retrieval import HashingEmbedder

    return {
        "openai": OpenAIEmbedder,
        "ollama": OllamaEmbedder,
        "bedrock": BedrockEmbedder,
    }.get(settings.embedder, lambda _s: HashingEmbedder())(settings)

assistant/graph.py:
"""Knowledge graph for questions that span people, roles, departments and documents.

Vector search is good at "what does the policy say?" and bad at "who owns it?" or "which
documents can nurses read?". Those are relationship questions, so they are answered from a
graph:

    (User)-[:HAS_ROLE]->(Role)          (User)-[:MEMBER_OF]->(Org)
    (User)-[:REPORTS_TO]->(User)        (User)-[:OWNS|APPROVED]->(Document)
    (Role)-[:CAN_READ]->(Document)      (Document)-[:BELONGS_TO]->(Org)
    (Document)-[:SUPERSEDES]->(Document)

The model never writes graph queries. A question is mapped to one of the fixed lookups in
`LOOKUPS` and only its parameters vary, so there is nothing to inject. Every lookup that
returns documents applies the same access rule as document search.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from .knowledge import Document, KnowledgeBase, User

_ACCESS = "Only documents that are approved, current, and readable by one of the asker's roles."

# Plain-language description of each fixed lookup, shown in the answer trace.
LOOKUPS: dict[str, str] = {
    "doc_owner": "Find the person who OWNS the document, and the department they're a MEMBER_OF. " + _ACCESS,
    "doc_approver": "Find the person who APPROVED the document, and the department they're a MEMBER_OF. " + _ACCESS,
    "role_documents": "List the documents the role CAN_READ, with the department each BELONGS_TO. " + _ACCESS,
    "user_manager": "Find the person this user REPORTS_TO, and that person's department.",
    "org_members": "List the people who are a MEMBER_OF the department.",
    "user_documents": "List the documents this person OWNS. " + _ACCESS,
}


@dataclass
class Edge:
    source: str
    rel: str
    target: str
    source_kind: str = ""
    target_kind: str = ""


@dataclass
class GraphAnswer:
    intent: str
    text: str
    rows: list[dict[str, Any]]
    path: list[Edge]
    lookup: str
    params: dict[str, Any]
    doc_ids: list[str] = field(default_factory=list)

    def as_dict(self) -> dict[str, Any]:
        d = self.__dict__.copy()
        d["path"] = [e.__dict__ for e in self.path]
        return d


class MemoryGraph:
    """In-process graph built from the knowledge base. Runs the fixed lookups in `LOOKUPS`."""

    def __init__(self, kb: KnowledgeBase) -> None:
        self.kb = kb

    def _allowed(self, doc: Document, params: dict[str, Any]) -> bool:
        if not params.get("guarded", True):
            return True
        roles = set(params.get("roles", []))
        return doc.status == "approved" and not doc.superseded_by and bool(roles & set(doc.audience))

    def _person(self, user: User) -> dict[str, Any]:
        return {
            "person_id": user.id,
            "person": user.name,
            "title": user.title,
            "org": self.kb.directory.org_name(user.org),
        }

    def run(self, intent: str, params: dict[str, Any]) -> list[dict[str, Any]]:
        kb, users = self.kb, self.kb.directory.users
        if intent in {"doc_owner", "doc_approver"}:
            doc = kb.docs.get(params["doc_id"])
            who = (doc.owner if intent == "doc_owner" else doc.approved_by) if doc else None
            if not doc or who not in users or not self._allowed(doc, params):
                return []
            return [{**self._person(users[who]), "doc_id": doc.id, "document": doc.title, "version": doc.version}]
        if intent == "role_documents":
            rows = [
                {"doc_id": d.id, "document": d.title, "version": d.version, "org": kb.directory.org_name(d.org)}
                for d in kb.docs.values()
                if params["role"] in d.audience and self._allowed(d, params)
            ]
            return sorted(rows, key=lambda r: (r["document"], r["version"]))
        if intent == "user_manager":
            user = users.get(params["user_id"])
            if not user or user.manager not in users:
                return []
            return [{"subject": user.name, **self._person(users[user.manager])}]
        if intent == "org_members":
            return sorted(
                (self._person(u) for u in users.values() if u.org == params["org_id"]), key=lambda r: r["person"]
            )
        if intent == "user_documents":
            user = users.get(params["user_id"])
            if not user:
                return []
            rows = [
                {"subject": user.name, "doc_id": d.id, "document": d.title, "version": d.version}
                for d in kb.docs.values()
                if d.owner == user.id and self._allowed(d, params)
            ]
            return sorted(rows, key=lambda r: (r["document"], r["version"]))
        raise ValueError(f"Unknown graph intent {intent!r}")

    # ---------- whole-graph view for the UI ----------

    def snapshot(self, viewer: User | None, guarded: bool = True) -> dict[str, Any]:
        """Nodes and edges, with documents the viewer can't use left out entirely."""
        kb = self.kb
        params = {"guarded": guarded, "roles": viewer.roles if viewer else []}
        docs = [d for d in kb.docs.values() if self._allowed(d, params)]
        nodes: list[dict[str, Any]] = []
        edges: list[dict[str, str]] = []
        for u in kb.directory.users.values():
            nodes.append({"id": f"user:{u.id}", "kind": "User", "label": u.name, "sub": u.title})
            edges.append({"source": f"user:{u.id}", "rel": "MEMBER_OF", "target": f"org:{u.org}"})
            if u.manager:
                edges.append({"source": f"user:{u.id}", "rel": "REPORTS_TO", "target": f"user:{u.manager}"})
            for r in u.roles:
                edges.append({"source": f"user:{u.id}", "rel": "HAS_ROLE", "target": f"role:{r}"})
        for o in kb.directory.orgs.values():
            nodes.append({"id": f"org:{o['id']}", "kind": "Org", "label": o["name"], "sub": ""})
        for r in kb.directory.roles.values():
            nodes.append({"id": f"role:{r['id']}", "kind": "Role", "label": r["name"], "sub": ""})
        for d in docs:
            nodes.append(
                {"id": f"doc:{d.id}", "kind": "Document", "label": d.title, "sub": f"v{d.version} · {d.status}"}
            )
            edges.append({"source": f"user:{d.owner}", "rel": "OWNS", "target": f"doc:{d.id}"})
            if d.approved_by:
                edges.append({"source": f"user:{d.approved_by}", "rel": "APPROVED", "target": f"doc:{d.id}"})
            edges.append({"source": f"doc:{d.id}", "rel": "BELONGS_TO", "target": f"org:{d.org}"})
            for r in d.audience:
                edges.append({"source": f"role:{r}", "rel": "CAN_READ", "target": f"doc:{d.id}"})
            if d.supersedes and d.supersedes in {x.id for x in docs}:
                edges.append({"source": f"doc:{d.id}", "rel": "SUPERSEDES", "target": f"doc:{d.supersedes}"})
        return {"nodes": nodes, "edges": edges}


def _doc_label(row: dict[str, Any]) -> str:
    return f"{row['document']} (v{row['version']})"


def explain(intent: str, params: dict[str, Any], rows: list[dict[str, Any]], kb: KnowledgeBase) -> GraphAnswer:
    """Turn template rows into an answer sentence and the graph path behind it."""
    lookup = LOOKUPS[intent]
    if not params.get("guarded", True) and _ACCESS in lookup:
        lookup = lookup.replace(_ACCESS, "Guardrails off: no access or lifecycle check.")
    shown = {k: v for k, v in params.items() if k != "guarded"}
    path: list[Edge] = []
    doc_ids = [r["doc_id"] for r in rows if "doc_id" in r]
    if not rows:
        return GraphAnswer(intent, "", [], [], lookup, shown, [])
    r0 = rows[0]
    if intent in {"doc_owner", "doc_approver"}:
        verb = "owns" if intent == "doc_owner" else "approved"
        rel = "OWNS" if intent == "doc_owner" else "APPROVED"
        text = f"{r0['person']} ({r0['title']}, {r0['org']}) {verb} the {_doc_label(r0)}."
        if params.get("topic"):
            text = f"Contact {r0['person']} ({r0['title']}, {r0['org']}), who owns the {_doc_label(r0)}."
        path = [
            Edge(r0["person"], rel, _doc_label(r0), "User", "Document"),
            Edge(r0["person"], "MEMBER_OF", r0["org"], "User", "Org"),
        ]
    elif intent == "role_documents":
        role = kb.directory.role_name(params["role"])
        names = ", ".join(_doc_label(r) for r in rows)
        text = f"The {role} role can read {len(rows)} document{'s' if len(rows) != 1 else ''} you also have access to: {names}."
        path = [Edge(role, "CAN_READ", _doc_label(r), "Role", "Document") for r in rows]
    elif intent == "user_manager":
        subject = "You report" if params.get("is_self") else f"{r0['subject']} reports"
        text = f"{subject} to {r0['person']} ({r0['title']}, {r0['org']})."
        path = [Edge(r0["subject"], "REPORTS_TO", r0["person"], "User", "User")]
    elif intent == "org_members":
        names = ", ".join(f"{r['person']} ({r['title']})" for r in rows)
        text = f"{r0['org']} has {len(rows)} member{'s' if len(rows) != 1 else ''}: {names}."
        path = [Edge(r["person"], "MEMBER_OF", r["org"], "User", "Org") for r in rows]
    elif intent == "user_documents":
        names = ", ".join(_doc_label(r) for r in rows)
        text = f"{r0['subject']} owns {len(rows)} document{'s' if len(rows) != 1 else ''} you can see: {names}."
        path = [Edge(r0["subject"], "OWNS", _doc_label(r), "User", "Document") for r in rows]
    else:
        raise ValueError(intent)
    return GraphAnswer(intent, text, rows, path, lookup, shown, doc_ids)

assistant/grounding.py:
"""Answer drafting and the grounding check that every answer must pass.

`extractive_answer` is the offline answerer: it quotes the sentences that best answer the
question, with no model involved. LLM answers are written by a model instead. Either way the
draft then goes through `verify`, which checks every sentence against the passages it cites:

* a sentence with no citation, or citing a source that wasn't provided, is dropped;
* a sentence whose content words aren't mostly in the cited passage is dropped;
* a sentence with a number, amount or percentage that isn't in the cited passage is dropped.
  (Wrong numbers are the most common and most harmful hallucination in policy answers.)

If nothing survives, the assistant abstains instead of answering.
"""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass, field

from .text import content_terms, numbers, split_sentences, strip_citations, tokenize


@dataclass
class Source:
    n: int  # citation number shown to the model and the user
    chunk_id: str
    doc_id: str
    title: str
    heading: str
    text: str


@dataclass
class Verdict:
    sentence: str
    cites: list[int]
    kept: bool
    reason: str  # supported | no_citation | unknown_source | low_support | number_mismatch
    support: float = 0.0


@dataclass
class Verification:
    answer: str
    verdicts: list[Verdict] = field(default_factory=list)

    @property
    def kept(self) -> list[Verdict]:
        return [v for v in self.verdicts if v.kept]

    @property
    def dropped(self) -> list[Verdict]:
        return [v for v in self.verdicts if not v.kept]

    @property
    def cited(self) -> list[int]:
        seen: list[int] = []
        for v in self.kept:
            for c in v.cites:
                if c not in seen:
                    seen.append(c)
        return seen


def coverage(question_tokens: list[str], text_tokens: set[str], idf: Callable[[str], float]) -> float:
    """IDF-weighted share of the question's terms that appear in the text."""
    q = set(question_tokens)
    if not q:
        return 0.0
    total = sum(idf(t) for t in q)
    return sum(idf(t) for t in q if t in text_tokens) / total if total else 0.0


def extractive_answer(
    question: str, sources: list[Source], idf: Callable[[str], float], max_sentences: int = 2
) -> tuple[str, float]:
    """Quote the best-matching sentence(s), each with its citation. Returns (answer, confidence).

    Confidence is the question-term coverage of the best sentence plus its section heading,
    so "Carryover: Employees may carry over up to 5 days" can answer "how many days carry over?".
    """
    q = content_terms(question)
    scored: list[tuple[float, int, int, str, Source]] = []
    for rank, src in enumerate(sources):
        head = set(tokenize(src.heading + " " + src.title))
        for i, sentence in enumerate(split_sentences(src.text)):
            toks = set(tokenize(sentence))
            cov = coverage(q, toks | head, idf)
            own = coverage(q, toks, idf)
            # Rank bonus is small: retrieval order breaks ties, sentence content decides.
            score = 0.75 * cov + 0.25 * own - 0.02 * rank
            scored.append((score, rank, i, sentence, src))
    if not scored:
        return "", 0.0
    scored.sort(key=lambda x: -x[0])
    best = scored[0]
    chosen = [best]
    for cand in scored[1:]:
        if len(chosen) >= max_sentences:
            break
        # A follow-up sentence must come from the same passage, right after the best one,
        # and still be about the question.
        if cand[4] is best[4] and cand[2] == best[2] + 1 and cand[0] >= 0.6 * best[0] and cand[0] > 0.25:
            chosen.append(cand)
    chosen.sort(key=lambda x: (x[1], x[2]))
    answer = " ".join(f"{s} [{src.n}]" for _, _, _, s, src in chosen)
    head = set(tokenize(best[4].heading + " " + best[4].title))
    confidence = coverage(q, set(tokenize(best[3])) | head, idf)
    return answer, round(confidence, 3)


def verify(answer: str, sources: list[Source], min_support: float = 0.6) -> Verification:
    by_n = {s.n: s for s in sources}
    result = Verification(answer=answer)
    for raw in split_sentences(answer):
        sentence, cites = strip_citations(raw)
        if not sentence:
            continue
        if not cites:
            result.verdicts.append(Verdict(sentence, cites, False, "no_citation"))
            continue
        if any(c not in by_n for c in cites):
            result.verdicts.append(Verdict(sentence, cites, False, "unknown_source"))
            continue
        cited_text = " ".join(by_n[c].heading + ". " + by_n[c].text for c in cites)
        s_toks = set(tokenize(sentence))
        support = len(s_toks & set(tokenize(cited_text))) / len(s_toks) if s_toks else 0.0
        if numbers(sentence) - numbers(cited_text):
            result.verdicts.append(Verdict(sentence, cites, False, "number_mismatch", round(support, 3)))
        elif support < min_support:
            result.verdicts.append(Verdict(sentence, cites, False, "low_support", round(support, 3)))
        else:
            result.verdicts.append(Verdict(sentence, cites, True, "supported", round(support, 3)))
    return result

assistant/knowledge.py:
"""The knowledge base: documents with lifecycle metadata, the people directory, and access policy.

The access policy lives here, in one function, and every path to content goes through it:
retrieval, graph lookups, source previews and the document list. A passage the asker can't
see is never ranked, never sent to a model and never counted in a response.
"""

from __future__ import annotations

import json
import re
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any

from .text import chunk_markdown

STATUSES = ("draft", "approved", "archived")


class KnowledgeError(ValueError):
    pass


@dataclass
class User:
    id: str
    name: str
    title: str
    org: str
    roles: list[str]
    manager: str | None = None

    @property
    def is_admin(self) -> bool:
        return "knowledge_admin" in self.roles


@dataclass
class Document:
    id: str
    title: str
    version: int
    status: str
    owner: str
    org: str
    audience: list[str]
    effective: str
    body: str
    approved_by: str | None = None
    supersedes: str | None = None
    superseded_by: str | None = None

    def summary(self) -> dict[str, Any]:
        d = asdict(self)
        d.pop("body")
        return d


@dataclass
class Chunk:
    id: str
    doc_id: str
    ord: int
    heading: str
    text: str

    @property
    def full_text(self) -> str:
        return f"{self.heading}. {self.text}" if self.heading else self.text


@dataclass
class Decision:
    allowed: bool
    reason: str  # ok | draft | archived | superseded | no_access


@dataclass
class Directory:
    users: dict[str, User]
    orgs: dict[str, dict[str, Any]]
    roles: dict[str, dict[str, Any]]
    demo_users: list[str] = field(default_factory=list)

    @classmethod
    def load(cls, path: Path) -> Directory:
        raw = json.loads(path.read_text())
        return cls(
            users={u["id"]: User(**u) for u in raw["users"]},
            orgs={o["id"]: o for o in raw["orgs"]},
            roles={r["id"]: r for r in raw["roles"]},
            demo_users=raw.get("demo_users", []),
        )

    def user(self, user_id: str) -> User:
        if user_id not in self.users:
            raise KnowledgeError(f"Unknown user {user_id!r}")
        return self.users[user_id]

    def name(self, user_id: str | None) -> str:
        return self.users[user_id].name if user_id in self.users else (user_id or "")

    def org_name(self, org_id: str) -> str:
        return self.orgs.get(org_id, {}).get("name", org_id)

    def role_name(self, role_id: str) -> str:
        return self.roles.get(role_id, {}).get("name", role_id)


def parse_front_matter(raw: str) -> tuple[dict[str, str], str]:
    m = re.match(r"^---\s*\n(.*?)\n---\s*\n(.*)$", raw, re.S)
    if not m:
        raise KnowledgeError("Document must start with a --- front matter block")
    meta = {}
    for line in m.group(1).splitlines():
        if ":" in line:
            key, value = line.split(":", 1)
            meta[key.strip()] = value.strip()
    return meta, m.group(2).strip()


def document_from_markdown(raw: str) -> Document:
    meta, body = parse_front_matter(raw)
    missing = {"id", "title", "status", "owner", "org", "audience"} - set(meta)
    if missing:
        raise KnowledgeError(f"Front matter is missing: {', '.join(sorted(missing))}")
    if meta["status"] not in STATUSES:
        raise KnowledgeError(f"status must be one of {STATUSES}")
    return Document(
        id=meta["id"],
        title=meta["title"],
        version=int(meta.get("version", "1")),
        status=meta["status"],
        owner=meta["owner"],
        org=meta["org"],
        audience=[a.strip() for a in meta["audience"].split(",") if a.strip()],
        effective=meta.get("effective", ""),
        body=body,
        approved_by=meta.get("approved_by") or None,
        supersedes=meta.get("supersedes") or None,
    )


class KnowledgeBase:
    def __init__(self, directory: Directory, chunk_words: int = 90) -> None:
        self.directory = directory
        self.docs: dict[str, Document] = {}
        self.chunks: dict[str, Chunk] = {}
        self.chunk_words = chunk_words
        self.version = 0  # bumps on every change so indexes know to rebuild

    @classmethod
    def load(cls, root: Path) -> KnowledgeBase:
        kb = cls(Directory.load(root / "directory.json"))
        for path in sorted((root / "documents").glob("*.md")):
            kb.add(document_from_markdown(path.read_text()))
        kb.link_versions()
        return kb

    def add(self, doc: Document) -> Document:
        if doc.id in self.docs:
            raise KnowledgeError(f"A document with id {doc.id!r} already exists")
        if doc.owner not in self.directory.users:
            raise KnowledgeError(f"Unknown owner {doc.owner!r}")
        unknown = set(doc.audience) - set(self.directory.roles)
        if unknown:
            raise KnowledgeError(f"Unknown audience role(s): {', '.join(sorted(unknown))}")
        self.docs[doc.id] = doc
        for i, (heading, text) in enumerate(chunk_markdown(doc.body, self.chunk_words)):
            c = Chunk(id=f"{doc.id}#{i}", doc_id=doc.id, ord=i, heading=heading, text=text)
            self.chunks[c.id] = c
        self.version += 1
        return doc

    def link_versions(self) -> None:
        for doc in self.docs.values():
            if doc.supersedes and doc.supersedes in self.docs and doc.status == "approved":
                self.docs[doc.supersedes].superseded_by = doc.id

    def approve(self, doc_id: str, approver: str) -> Document:
        doc = self.docs[doc_id]
        if doc.status != "draft":
            raise KnowledgeError(f"Only drafts can be approved; this document is {doc.status}")
        doc.status, doc.approved_by = "approved", approver
        if doc.supersedes and doc.supersedes in self.docs:
            old = self.docs[doc.supersedes]
            old.status, old.superseded_by = "archived", doc.id
        self.version += 1
        return doc

    # ---------- the access policy ----------

    def can_read(self, user: User, doc: Document) -> bool:
        return bool(set(user.roles) & set(doc.audience))

    def decide(self, user: User, doc: Document) -> Decision:
        """May this passage be used to answer this user? Order matters: access is checked first,
        so a restricted draft reports `no_access` and its lifecycle state is never revealed."""
        if not self.can_read(user, doc):
            return Decision(False, "no_access")
        if doc.status == "draft":
            return Decision(False, "draft")
        if doc.status == "archived" or doc.superseded_by:
            return Decision(False, "archived")
        return Decision(True, "ok")

    def visible_docs(self, user: User) -> list[Document]:
        """Documents listed for this user. Knowledge admins also see drafts and archives they can read."""
        out = []
        for doc in self.docs.values():
            d = self.decide(user, doc)
            if d.allowed or (user.is_admin and d.reason in {"draft", "archived"}):
                out.append(doc)
        return sorted(out, key=lambda d: (d.title, -d.version))

assistant/retrieval.py:
"""Permission-aware hybrid retrieval.

BM25 catches exact terms ("Sev1", "PTO"); dense vectors catch paraphrases. The two rankings
are merged with Reciprocal Rank Fusion. The access filter is applied *before* ranking, in
both retrievers, so a passage the asker can't use never competes for a slot in the context.

Dense search goes through the `VectorStore` interface. `MemoryVectorStore` is the default;
`backends.pinecone` and `backends.weaviate` push the same filter down into those databases.
"""

from __future__ import annotations

import hashlib
import math
import threading
from collections import Counter
from collections.abc import Sequence
from dataclasses import dataclass
from typing import Any, Protocol

from .knowledge import Chunk, KnowledgeBase
from .text import tokenize


class Embedder(Protocol):
    name: str

    def embed(self, texts: Sequence[str]) -> list[list[float]]: ...


class HashingEmbedder:
    """Local, deterministic embeddings via feature hashing of unigrams and bigrams.

    No model download and no API cost, so the demo runs anywhere, including in a browser.
    Swap in OpenAI, Bedrock Titan or Ollama embeddings with ASSISTANT_EMBEDDER.
    """

    name = "hashing-512"

    def __init__(self, dim: int = 512) -> None:
        self.dim = dim

    def _bucket(self, feature: str) -> tuple[int, float]:
        h = int.from_bytes(hashlib.blake2b(feature.encode(), digest_size=8).digest(), "big")
        return h % self.dim, (1.0 if (h >> 63) & 1 else -1.0)

    def embed(self, texts: Sequence[str]) -> list[list[float]]:
        out = []
        for text in texts:
            toks = tokenize(text)
            feats = Counter(toks + [f"{a}_{b}" for a, b in zip(toks, toks[1:], strict=False)])
            vec = [0.0] * self.dim
            for feat, tf in feats.items():
                idx, sign = self._bucket(feat)
                vec[idx] += sign * (1.0 + math.log(tf))
            norm = math.sqrt(sum(v * v for v in vec)) or 1.0
            out.append([v / norm for v in vec])
        return out


# ---------- access filter, expressed as data so vector databases can apply it ----------


@dataclass(frozen=True)
class AccessFilter:
    """None roles = no filtering (naive mode, used only for comparison and evaluation)."""

    roles: tuple[str, ...] | None

    @property
    def active(self) -> bool:
        return self.roles is not None

    def matches(self, meta: dict[str, Any]) -> bool:
        if self.roles is None:
            return True
        return meta["status"] == "approved" and meta["current"] and bool(set(self.roles) & set(meta["audience"]))


def chunk_metadata(kb: KnowledgeBase, chunk: Chunk) -> dict[str, Any]:
    doc = kb.docs[chunk.doc_id]
    return {
        "doc_id": doc.id,
        "status": doc.status,
        "current": doc.superseded_by is None,
        "audience": list(doc.audience),
        "org": doc.org,
    }


class VectorStore(Protocol):
    name: str

    def upsert(self, items: list[tuple[str, list[float], dict[str, Any]]]) -> None: ...

    def query(self, vector: list[float], k: int, flt: AccessFilter) -> list[tuple[str, float]]: ...


class MemoryVectorStore:
    name = "memory"

    def __init__(self) -> None:
        self.items: dict[str, tuple[list[float], dict[str, Any]]] = {}

    def upsert(self, items: list[tuple[str, list[float], dict[str, Any]]]) -> None:
        for cid, vec, meta in items:
            self.items[cid] = (vec, meta)

    def query(self, vector: list[float], k: int, flt: AccessFilter) -> list[tuple[str, float]]:
        scored = []
        for cid, (vec, meta) in self.items.items():
            if not flt.matches(meta):
                continue
            s = sum(x * y for x, y in zip(vector, vec, strict=False))
            if s > 0.05:
                scored.append((cid, s))
        return sorted(scored, key=lambda x: -x[1])[:k]


@dataclass
class Hit:
    chunk_id: str
    doc_id: str
    score: float
    bm25_rank: int | None
    vector_rank: int | None


class HybridRetriever:
    def __init__(self, kb: KnowledgeBase, embedder: Embedder, store: VectorStore, k1: float = 1.5, b: float = 0.75):
        self.kb, self.embedder, self.store = kb, embedder, store
        self.k1, self.b = k1, b
        self._lock = threading.Lock()
        self._built_version = -1
        self._embedded: set[str] = set()

    def _build(self) -> None:
        """(Re)index when the knowledge base changes. Only new chunks are embedded;
        metadata (status, audience) is re-sent for all, since approvals change it."""
        kb = self.kb
        self.ids = list(kb.chunks)
        self.meta = {cid: chunk_metadata(kb, kb.chunks[cid]) for cid in self.ids}
        self.tokens = {
            cid: tokenize(kb.chunks[cid].full_text + " " + kb.docs[kb.chunks[cid].doc_id].title) for cid in self.ids
        }
        self.tf = {cid: Counter(t) for cid, t in self.tokens.items()}
        self.avgdl = sum(len(t) for t in self.tokens.values()) / max(1, len(self.tokens))
        df: Counter[str] = Counter()
        for t in self.tokens.values():
            df.update(set(t))
        n = len(self.ids)
        self.idf = {term: math.log(1 + (n - d + 0.5) / (d + 0.5)) for term, d in df.items()}
        new = [cid for cid in self.ids if cid not in self._embedded]
        vectors = dict(zip(new, self.embedder.embed([kb.chunks[c].full_text for c in new]), strict=True)) if new else {}
        if isinstance(self.store, MemoryVectorStore):
            self.store.upsert([(cid, vectors[cid], self.meta[cid]) for cid in new])
            for cid in self.ids:  # refresh metadata in place
                vec, _ = self.store.items[cid]
                self.store.items[cid] = (vec, self.meta[cid])
        else:
            missing = [cid for cid in self.ids if cid not in vectors]
            if missing:  # external stores need the vector re-sent with new metadata
                vectors.update(
                    zip(missing, self.embedder.embed([kb.chunks[c].full_text for c in missing]), strict=True)
                )
            self.store.upsert([(cid, vectors[cid], self.meta[cid]) for cid in self.ids])
        self._embedded.update(new)
        self._built_version = kb.version

    def ensure_built(self) -> None:
        with self._lock:
            if self._built_version != self.kb.version:
                self._build()

    def idf_of(self, term: str) -> float:
        return self.idf.get(term, math.log(1 + len(self.ids)))

    def _bm25(self, query: str, flt: AccessFilter) -> list[tuple[str, float]]:
        q = tokenize(query)
        scores = []
        for cid in self.ids:
            if not flt.matches(self.meta[cid]):
                continue
            tf, dl, s = self.tf[cid], len(self.tokens[cid]), 0.0
            for term in q:
                f = tf.get(term)
                if f:
                    s += (
                        self.idf[term]
                        * f
                        * (self.k1 + 1)
                        / (f + self.k1 * (1 - self.b + self.b * dl / (self.avgdl or 1)))
                    )
            if s > 0:
                scores.append((cid, s))
        return sorted(scores, key=lambda x: -x[1])

    def search(self, query: str, flt: AccessFilter, k: int = 6, rrf_k: int = 60) -> list[Hit]:
        self.ensure_built()
        if not query.strip():
            return []
        bm25 = self._bm25(query, flt)[: k * 3]
        dense = self.store.query(self.embedder.embed([query])[0], k * 3, flt)
        b_rank = {cid: r for r, (cid, _) in enumerate(bm25, 1)}
        v_rank = {cid: r for r, (cid, _) in enumerate(dense, 1)}
        fused: dict[str, float] = {}
        for ranks in (b_rank, v_rank):
            for cid, r in ranks.items():
                fused[cid] = fused.get(cid, 0.0) + 1.0 / (rrf_k + r)
        top = sorted(fused.items(), key=lambda x: -x[1])[:k]
        best = top[0][1] if top else 1.0
        return [
            Hit(cid, self.kb.chunks[cid].doc_id, round(s / best, 3), b_rank.get(cid), v_rank.get(cid)) for cid, s in top
        ]

assistant/router.py:
"""Decide whether a question goes to the knowledge graph, to document search, or both.

Relationship questions ("who owns…", "who approved…", "which documents can nurses read?",
"who do I report to?") go to the graph. "Who should I contact about X?" uses both: search
finds the document about X, and the graph finds its owner. Everything else is document search.

The rules below are deterministic and fast. With an LLM provider configured, the model may
pick the intent instead, but only from the same fixed menu, and its choice is validated
before use; anything unexpected falls back to these rules.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from typing import Any

from .knowledge import KnowledgeBase, User
from .text import tokenize

GRAPH_INTENTS = (
    "doc_owner",
    "doc_approver",
    "topic_contact",
    "role_documents",
    "user_manager",
    "org_members",
    "user_documents",
)

_PATTERNS: list[tuple[str, re.Pattern[str]]] = [
    ("doc_approver", re.compile(r"\bwho (approved|signed off( on)?)\b", re.I)),
    (
        "topic_contact",
        re.compile(
            r"\bwho (should|do|can) i (ask|contact|talk to|call|email|reach out to)\b|\bwho to (ask|contact)\b", re.I
        ),
    ),
    (
        "user_manager",
        re.compile(
            r"\bwho (do|does) (\w+) report to\b|\bwho is (my|\w+'s) (manager|boss|supervisor)\b|\b(manager|boss) of \w+",
            re.I,
        ),
    ),
    (
        "user_documents",
        re.compile(r"\b(which|what) (documents|docs|policies|procedures)\b.*\b(does|do) (\w+) own\b", re.I),
    ),
    ("doc_owner", re.compile(r"\bwho (owns|maintains|wrote|is responsible for)\b|\bowner of\b", re.I)),
    (
        "role_documents",
        re.compile(
            r"\b(which|what) (documents|docs|policies|procedures)\b.*\b(can|may|do)\b.*\b(read|see|access|view)\b", re.I
        ),
    ),
    ("org_members", re.compile(r"\bwho (works|is|are) (in|on)\b|\bmembers of\b", re.I)),
]

# Words that appear in many titles and say nothing about which document is meant.
_GENERIC = {"policy", "procedure", "guide", "guideline", "runbook", "document", "sop", "monitor"}


@dataclass
class Route:
    kind: str  # documents | graph | both
    intent: str | None = None
    params: dict[str, Any] = field(default_factory=dict)
    reason: str = ""
    by: str = "rules"


def _find_user(question: str, asker: User, kb: KnowledgeBase) -> tuple[str | None, bool]:
    q = question.lower()
    if re.search(r"\b(i|my|me)\b", q):
        return asker.id, True
    for u in kb.directory.users.values():
        first = u.name.split()[0].lower()
        if u.name.lower() in q or re.search(rf"\b{re.escape(first)}('s)?\b", q):
            return u.id, u.id == asker.id
    return None, False


def _find_alias(question: str, items: dict[str, dict[str, Any]]) -> str | None:
    q = f" {question.lower()} "
    best: tuple[int, str] | None = None
    for item_id, item in items.items():
        for alias in [item["name"].lower(), *item.get("aliases", [])]:
            if re.search(rf"\b{re.escape(alias)}\b", q) and (best is None or len(alias) > best[0]):
                best = (len(alias), item_id)
    return best[1] if best else None


def find_document(question: str, kb: KnowledgeBase, candidates: list[str]) -> str | None:
    """Match a document by its title. Candidates are the documents the asker may use."""
    q = set(tokenize(question))
    best: tuple[float, int, str] | None = None
    for doc_id in candidates:
        doc = kb.docs[doc_id]
        title = set(tokenize(doc.title))
        specific = title - _GENERIC
        hits = q & specific
        if not hits:
            continue
        score = len(q & title) / len(title)
        key = (score, doc.version, doc_id)
        if best is None or key > best:
            best = key
    return best[2] if best and best[0] >= 0.5 else None


def route(question: str, asker: User, kb: KnowledgeBase, candidates: list[str]) -> Route:
    for intent, pattern in _PATTERNS:
        if not pattern.search(question):
            continue
        if intent in {"doc_owner", "doc_approver"}:
            doc_id = find_document(question, kb, candidates)
            if doc_id:
                return Route("graph", intent, {"doc_id": doc_id}, f"Asks who {intent.split('_')[1]}s a named document")
            # No title match: search finds the document, the graph answers the same question.
            return Route(
                "both", intent, {"topic": question}, "Asks about a document's people; search finds the document"
            )
        if intent == "topic_contact":
            return Route(
                "both",
                "topic_contact",
                {"topic": question},
                "Asks who to contact; search finds the document, the graph finds its owner",
            )
        if intent in {"user_manager", "user_documents"}:
            user_id, is_self = _find_user(question, asker, kb)
            if user_id:
                return Route(
                    "graph", intent, {"user_id": user_id, "is_self": is_self}, "Asks about a person's relationships"
                )
        if intent == "role_documents":
            role = _find_alias(question, kb.directory.roles)
            if role:
                return Route("graph", intent, {"role": role}, "Asks which documents a role can read")
        if intent == "org_members":
            org = _find_alias(question, kb.directory.orgs)
            if org:
                return Route("graph", intent, {"org_id": org}, "Asks who belongs to a department")
    return Route("documents", None, {}, "Asks what the documents say")


ROUTER_PROMPT = """You route questions for an enterprise knowledge assistant.
Pick ONE intent:
- documents: the answer is in the text of a policy or procedure
- doc_owner / doc_approver: who owns / approved a named document (give "document": its title words)
- topic_contact: who to contact about a topic
- role_documents: which documents a role can read (give "role": one of {roles})
- user_manager: who someone reports to (give "user": one of {users}, or "me")
- org_members: who works in a department (give "org": one of {orgs})
- user_documents: which documents a person owns (give "user")
Reply with JSON only: {{"intent": "...", "document": "", "role": "", "user": "", "org": ""}}"""


def route_with_llm(provider: Any, question: str, asker: User, kb: KnowledgeBase, candidates: list[str]) -> Route:
    """Let a model choose from the fixed menu; validate everything it returns."""
    fallback = route(question, asker, kb, candidates)
    try:
        raw = provider.complete(
            ROUTER_PROMPT.format(
                roles=", ".join(kb.directory.roles),
                users=", ".join(kb.directory.users),
                orgs=", ".join(kb.directory.orgs),
            ),
            question,
            json_mode=True,
        )
        choice = json.loads(raw[raw.find("{") : raw.rfind("}") + 1])
    except Exception:  # any provider or parsing failure: use the rules
        return fallback
    intent = choice.get("intent")
    if intent == "documents":
        return Route("documents", None, {}, "Model: answer is in document text", "model")
    if intent in {"doc_owner", "doc_approver"}:
        doc_id = find_document(str(choice.get("document", "")) or question, kb, candidates)
        if doc_id:
            return Route("graph", intent, {"doc_id": doc_id}, "Model: asks about a named document", "model")
        return Route("both", intent, {"topic": question}, "Model: asks about a document's people", "model")
    if intent == "topic_contact":
        return Route("both", "topic_contact", {"topic": question}, "Model: asks who to contact", "model")
    if intent == "role_documents" and choice.get("role") in kb.directory.roles:
        return Route("graph", intent, {"role": choice["role"]}, "Model: documents for a role", "model")
    if intent in {"user_manager", "user_documents"}:
        user = choice.get("user")
        user = asker.id if user == "me" else user
        if user in kb.directory.users:
            return Route(
                "graph", intent, {"user_id": user, "is_self": user == asker.id}, "Model: about a person", "model"
            )
    if intent == "org_members" and choice.get("org") in kb.directory.orgs:
        return Route("graph", intent, {"org_id": choice["org"]}, "Model: members of a department", "model")
    return fallback

